arguments.file_text:
.settings-container {
    display: flex;
    min-height: calc(100vh - 4rem);
    max-width: 1200px;
    margin: 0 auto;
    gap: 2rem;
    padding: 2rem;
}

/* Sidebar */
.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.settings-sidebar h2 {
    font-size: 1.25rem;
    margin-bottom: 1rem;
    color: #1a1a2e;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1rem;
    border-radius: 8px;
    cursor: pointer;
    margin-bottom: 0.25rem;
    transition: background-color 0.2s, color 0.2s;
    color: #555;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.settings-sidebar li:hover {
    background-color: #f0f0f5;
    color: #1a1a2e;
}

.settings-sidebar li.active {
    background-color: #4f46e5;
    color: #fff;
}

.settings-sidebar li .icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h3 {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.settings-section h4 {
    font-size: 1.1rem;
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    color: #333;
}

/* Forms */
.form-fields {
    max-width: 600px;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #4f46e5;
    box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    background-color: #4f46e5;
    color: #fff;
    border: none;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 500;
    transition: background-color 0.2s;
}

.btn-primary:hover {
    background-color: #4338ca;
}

.btn-secondary {
    background-color: #f3f4f6;
    color: #374151;
    border: 1px solid #d1d5db;
    padding: 0.6rem 1.25rem;
    border-radius: 6px;
    cursor: pointer;
